#!/usr/bin/env python3
import rclpy
from rclpy.node import Node
from sensor_msgs.msg import Joy
import tkinter as tk
from tkinter import ttk, font
import threading
import time

class InterfaceMonitor(Node):
    def __init__(self):
        super().__init__('interface_monitor')
        
        # UI Setup
        self.root = tk.Tk()
        self.root.title("Antigravity Interface Monitor")
        self.root.geometry("800x600")
        self.root.configure(bg='#111111')
        
        self.custom_font = font.Font(family="Courier", size=10, weight="bold")
        self.header_font = font.Font(family="Courier", size=12, weight="bold")
        
        self.colors = {
            'bg': '#111111',
            'card': '#222222',
            'axis': '#21918c',
            'button_off': '#3b528b',
            'button_on': '#fde725',
            'text': '#ffffff',
            'accent': '#440154'
        }

        # Internal state
        self.topic_data = {} # topic_name -> {sub, axes_widgets, button_widgets, labels}
        
        self._setup_ui()
        self.rescan_environment()

    def _setup_ui(self):
        # Toolbar
        toolbar = tk.Frame(self.root, bg=self.colors['accent'], pady=5)
        toolbar.pack(fill='x')
        
        tk.Button(toolbar, text="RE-SCAN ENVIRONMENT", command=self.rescan_environment,
                  bg=self.colors['button_off'], fg=self.colors['text'],
                  font=self.custom_font, relief=tk.FLAT).pack(pady=5)

        # Scrollable area
        self.canvas = tk.Canvas(self.root, bg=self.colors['bg'], highlightthickness=0)
        self.scrollbar = ttk.Scrollbar(self.root, orient="vertical", command=self.canvas.yview)
        self.scrollable_frame = tk.Frame(self.canvas, bg=self.colors['bg'])

        self.scrollable_frame.bind(
            "<Configure>",
            lambda e: self.canvas.configure(scrollregion=self.canvas.bbox("all"))
        )

        self.canvas.create_window((0, 0), window=self.scrollable_frame, anchor="nw")
        self.canvas.configure(yscrollcommand=self.scrollbar.set)

        self.canvas.pack(side="left", fill="both", expand=True, padx=10, pady=10)
        self.scrollbar.pack(side="right", fill="y")

    def rescan_environment(self):
        self.get_logger().info("Scanning for Joy topics...")
        topic_names_and_types = self.get_topic_names_and_types()
        
        joy_topics = [t[0] for t in topic_names_and_types if 'sensor_msgs/msg/Joy' in t[1]]
        
        # Remove old topics that are no longer present
        current_topics = list(self.topic_data.keys())
        for topic in current_topics:
            if topic not in joy_topics:
                self.get_logger().info(f"Removing topic: {topic}")
                self.topic_data[topic]['frame'].destroy()
                self.destroy_subscription(self.topic_data[topic]['sub'])
                del self.topic_data[topic]

        # Add new topics
        for topic in joy_topics:
            if topic not in self.topic_data:
                self._add_topic_monitor(topic)

    def _add_topic_monitor(self, topic):
        self.get_logger().info(f"Adding monitor for: {topic}")
        
        # Create a card for this topic
        frame = tk.Frame(self.scrollable_frame, bg=self.colors['card'], padx=15, pady=15, bd=1, relief=tk.RIDGE)
        frame.pack(fill='x', pady=5, padx=5)
        
        tk.Label(frame, text=f"TOPIC: {topic}", bg=self.colors['card'], fg=self.colors['button_on'], font=self.header_font).pack(anchor='w')
        
        content_frame = tk.Frame(frame, bg=self.colors['card'])
        content_frame.pack(fill='both', expand=True, pady=10)
        
        self.topic_data[topic] = {
            'frame': frame,
            'axis_widgets': [],
            'button_widgets': [],
            'axis_label_widgets': [],
            'button_label_widgets': [],
            'content_frame': content_frame,
            'initialized': False,
            'node_name': None
        }

        # Find the node publishing this topic
        pubs = self.get_publishers_info_by_topic(topic)
        if pubs:
            self.topic_data[topic]['node_name'] = pubs[0].node_name
            # Start a background thread to fetch parameters
            threading.Thread(target=self._fetch_params, args=(topic, pubs[0].node_name), daemon=True).start()

        # Subscribe
        sub = self.create_subscription(Joy, topic, lambda msg, t=topic: self._joy_callback(msg, t), 10)
        self.topic_data[topic]['sub'] = sub

    def _fetch_params(self, topic, node_name):
        from rcl_interfaces.srv import GetParameters
        client = self.create_client(GetParameters, f'{node_name}/get_parameters')
        
        if not client.wait_for_service(timeout_sec=2.0):
            return
            
        req = GetParameters.Request()
        req.names = ['axis_names', 'button_names']
        future = client.call_async(req)
        
        # Wait for result
        start_time = time.time()
        while time.time() - start_time < 2.0:
            if future.done():
                result = future.result()
                axis_names = result.values[0].string_array_value
                button_names = result.values[1].string_array_value
                
                # Update UI in main thread
                self.root.after(0, lambda: self._update_labels(topic, axis_names, button_names))
                return
            time.sleep(0.1)

    def _update_labels(self, topic, axis_names, button_names):
        if topic not in self.topic_data: return
        data = self.topic_data[topic]
        
        for i, name in enumerate(axis_names):
            if i < len(data['axis_label_widgets']):
                data['axis_label_widgets'][i].configure(text=name)
        
        for i, name in enumerate(button_names):
            if i < len(data['button_label_widgets']):
                data['button_label_widgets'][i].configure(text=name)

    def _joy_callback(self, msg, topic):
        if topic not in self.topic_data:
            return
            
        data = self.topic_data[topic]
        
        # Initialize widgets on first message
        if not data['initialized']:
            self._init_widgets(topic, len(msg.axes), len(msg.buttons))
            data['initialized'] = True
            
        # Update Axes
        for i, val in enumerate(msg.axes):
            if i < len(data['axis_widgets']):
                data['axis_widgets'][i].set(val)
                
        # Update Buttons
        for i, val in enumerate(msg.buttons):
            if i < len(data['button_widgets']):
                color = self.colors['button_on'] if val > 0 else self.colors['button_off']
                data['button_widgets'][i].configure(bg=color)

    def _init_widgets(self, topic, num_axes, num_buttons):
        data = self.topic_data[topic]
        parent = data['content_frame']
        
        # Axes Frame
        axes_frame = tk.Frame(parent, bg=self.colors['card'])
        axes_frame.pack(side='left', fill='y', padx=10)
        tk.Label(axes_frame, text="AXES", bg=self.colors['card'], fg=self.colors['text'], font=self.custom_font).pack()
        
        for i in range(num_axes):
            f = tk.Frame(axes_frame, bg=self.colors['card'])
            f.pack(fill='x')
            lbl = tk.Label(f, text=f"Axis {i}", bg=self.colors['card'], fg=self.colors['text'], font=self.custom_font, width=12, anchor='w')
            lbl.pack(side='left')
            data['axis_label_widgets'].append(lbl)
            
            s = tk.Scale(f, from_=-1.0, to=1.0, resolution=0.01, orient=tk.HORIZONTAL,
                         bg=self.colors['card'], fg=self.colors['axis'], length=150,
                         troughcolor='#333333', highlightthickness=0, state='disabled')
            s.pack(side='left')
            data['axis_widgets'].append(s)
            
        # Buttons Frame
        btns_frame = tk.Frame(parent, bg=self.colors['card'])
        btns_frame.pack(side='left', fill='both', expand=True, padx=10)
        tk.Label(btns_frame, text="BUTTONS", bg=self.colors['card'], fg=self.colors['text'], font=self.custom_font).pack()
        
        grid_frame = tk.Frame(btns_frame, bg=self.colors['card'])
        grid_frame.pack()
        
        for i in range(num_buttons):
            row = i // 4
            col = i % 4
            f = tk.Frame(grid_frame, bg=self.colors['card'], padx=2, pady=2)
            f.grid(row=row, column=col)
            
            box = tk.Label(f, text="", width=2, height=1,
                         bg=self.colors['button_off'], fg=self.colors['text'],
                         font=self.custom_font, relief=tk.FLAT)
            box.pack(side='left')
            data['button_widgets'].append(box)
            
            lbl = tk.Label(f, text=str(i), bg=self.colors['card'], fg=self.colors['text'], font=self.custom_font, width=10, anchor='w')
            lbl.pack(side='left', padx=2)
            data['button_label_widgets'].append(lbl)

def main(args=None):
    rclpy.init(args=args)
    node = InterfaceMonitor()
    
    def ros_loop():
        rclpy.spin_once(node, timeout_sec=0)
        node.root.after(10, ros_loop)
        
    node.root.after(10, ros_loop)
    try:
        node.root.mainloop()
    except KeyboardInterrupt:
        pass
    finally:
        node.destroy_node()
        rclpy.shutdown()

if __name__ == '__main__':
    main()
